3	// route_status.go implements `fiz route-status --overrides`
4	// (ADR-006 §5). The base `route-status` command lives in routing_smart.go
5	// and dispatches into this file when --overrides is set.
6	//
7	// This is the operator-facing surface that prints override_class_breakdown
8	// over a recent time window so operators can diagnose where auto-routing
9	// is mis-deciding. Per ADR-006 §Migration, this is an operator-driven
10	// feedback loop; automatic learning from this signal is a future ADR.
11	
12	import (
13		"context"
14		"encoding/json"
15		"fmt"
16		"io"
17		"os"
18		"sort"
19		"text/tabwriter"
20		"time"
21	
22		rootfizeau "github.com/DocumentDrivenDX/fizeau"
23		agentConfig "github.com/DocumentDrivenDX/fizeau/internal/config"
24	)
25	
26	const defaultRouteStatusOverridesWindow = 7 * 24 * time.Hour
27	
28	// routeStatusOverridesOutput is the stable JSON envelope emitted by
29	// `route-status --overrides --json`. The shape is snapshot-tested in
30	// TestRouteStatusOverridesJSONStable; new fields must be added at the end
31	// or behind a new flag.
32	type routeStatusOverridesOutput struct {
33		Since                    string                           `json:"since"`
34		WindowStart              time.Time                        `json:"window_start"`
35		WindowEnd                time.Time                        `json:"window_end"`
36		AxisFilter               string                           `json:"axis_filter,omitempty"`
37		AutoAcceptanceRate       float64                          `json:"auto_acceptance_rate"`
38		OverrideDisagreementRate float64                          `json:"override_disagreement_rate"`
39		TotalRequests            int                              `json:"total_requests"`
40		TotalOverrides           int                              `json:"total_overrides"`
41		OverrideClassBreakdown   []rootfizeau.OverrideClassBucket `json:"override_class_breakdown"`
42	}
