44	// cmdRouteStatusOverrides implements the --overrides mode. It is wired in
45	// from cmdRouteStatus (routing_smart.go); kept here to keep the operator
46	// surface self-contained.
47	func cmdRouteStatusOverrides(workDir, since, axis string, jsonOut bool) int {
48		return runRouteStatusOverrides(workDir, since, axis, jsonOut, os.Stdout, os.Stderr, time.Now().UTC())
49	}
50	
51	func runRouteStatusOverrides(workDir, since, axis string, jsonOut bool, stdout, stderr io.Writer, now time.Time) int {
52		if err := validateRouteStatusOverridesAxis(axis); err != nil {
53			fmt.Fprintf(stderr, "error: %s\n", err)
54			return 2
55		}
56	
57		dur, err := parseRouteStatusOverridesSince(since)
58		if err != nil {
59			fmt.Fprintf(stderr, "error: %s\n", err)
60			return 2
61		}
62		start := now.Add(-dur)
63		end := now
64	
65		cfg, err := agentConfig.Load(workDir)
66		if err != nil {
67			fmt.Fprintf(stderr, "error: %s\n", err)
68			return 1
69		}
70		svc, err := rootfizeau.New(rootfizeau.ServiceOptions{
71			ServiceConfig: agentConfig.NewServiceConfig(cfg, workDir),
72			SessionLogDir: sessionLogDir(workDir, cfg),
73		})
74		if err != nil {
75			fmt.Fprintf(stderr, "error: %s\n", err)
76			return 1
77		}
78	
79		report, err := svc.UsageReport(context.Background(), rootfizeau.UsageReportOptions{
80			Since: formatUsageWindowSince(start, end),
81			Now:   now,
82		})
83		if err != nil {
84			fmt.Fprintf(stderr, "error: %s\n", err)
85			return 1
86		}
87	
88		metrics := report.RoutingQuality
89		filtered := filterOverrideBreakdownByAxis(metrics.OverrideClassBreakdown, axis)
90	
91		out := routeStatusOverridesOutput{
92			Since:                    since,
93			WindowStart:              start,
94			WindowEnd:                end,
95			AxisFilter:               axis,
96			AutoAcceptanceRate:       metrics.AutoAcceptanceRate,
97			OverrideDisagreementRate: metrics.OverrideDisagreementRate,
98			TotalRequests:            metrics.TotalRequests,
99			TotalOverrides:           metrics.TotalOverrides,
100			OverrideClassBreakdown:   filtered,
101		}
102		if out.OverrideClassBreakdown == nil {
103			out.OverrideClassBreakdown = []rootfizeau.OverrideClassBucket{}
104		}
105	
106		if jsonOut {
107			writeRouteStatusOverridesJSON(stdout, out)
108			return 0
109		}
110		writeRouteStatusOverridesText(stdout, out)
111		return 0
112	}
