114	// parseRouteStatusOverridesSince parses --since as a Go duration. Empty
115	// means the default 7d window.
116	func parseRouteStatusOverridesSince(spec string) (time.Duration, error) {
117		if spec == "" {
118			return defaultRouteStatusOverridesWindow, nil
119		}
120		d, err := time.ParseDuration(spec)
121		if err != nil {
122			return 0, fmt.Errorf("--since: %w", err)
123		}
124		if d <= 0 {
125			return 0, fmt.Errorf("--since: must be positive, got %s", spec)
126		}
127		return d, nil
128	}
129	
130	// validateRouteStatusOverridesAxis rejects unknown axis values. Empty is
131	// allowed (no filter).
132	func validateRouteStatusOverridesAxis(axis string) error {
133		switch axis {
134		case "", "harness", "provider", "model":
135			return nil
136		default:
137			return fmt.Errorf("--axis: must be one of harness|provider|model, got %q", axis)
138		}
139	}
140	
141	// filterOverrideBreakdownByAxis returns rows where Axis == axis. Empty axis
142	// returns the input unchanged. Rows are returned in the same deterministic
143	// order produced by the aggregator.
144	func filterOverrideBreakdownByAxis(rows []rootfizeau.OverrideClassBucket, axis string) []rootfizeau.OverrideClassBucket {
145		if axis == "" {
146			return rows
147		}
148		out := make([]rootfizeau.OverrideClassBucket, 0, len(rows))
149		for _, r := range rows {
150			if r.Axis == axis {
151				out = append(out, r)
152			}
153		}
154		return out
155	}
156	
157	// sortOverrideBreakdownForDisplay returns a copy sorted by Count desc, then
158	// success rate desc, then deterministic key. The default JSON ordering is
159	// preserved by the aggregator; this is the table-render ordering.
160	func sortOverrideBreakdownForDisplay(rows []rootfizeau.OverrideClassBucket) []rootfizeau.OverrideClassBucket {
161		out := make([]rootfizeau.OverrideClassBucket, len(rows))
162		copy(out, rows)
163		sort.SliceStable(out, func(i, j int) bool {
164			if out[i].Count != out[j].Count {
165				return out[i].Count > out[j].Count
166			}
167			li := bucketSuccessRate(out[i])
168			lj := bucketSuccessRate(out[j])
169			if li != lj {
170				return li > lj
171			}
172			if out[i].PromptFeatureBucket != out[j].PromptFeatureBucket {
173				return out[i].PromptFeatureBucket < out[j].PromptFeatureBucket
174			}
175			if out[i].Axis != out[j].Axis {
176				return out[i].Axis < out[j].Axis
177			}
178			return !out[i].Match && out[j].Match
179		})
180		return out
181	}
182	
183	func bucketSuccessRate(b rootfizeau.OverrideClassBucket) float64 {
184		total := b.SuccessOutcomes + b.StalledOutcomes + b.FailedOutcomes + b.CancelledOutcomes + b.UnknownOutcomes
185		if total == 0 {
186			return 0
187		}
188		return float64(b.SuccessOutcomes) / float64(total)
189	}
190	
191	func writeRouteStatusOverridesJSON(w io.Writer, out routeStatusOverridesOutput) {
192		enc := json.NewEncoder(w)
193		enc.SetIndent("", "  ")
194		_ = enc.Encode(out)
195	}
196	
197	func writeRouteStatusOverridesText(w io.Writer, out routeStatusOverridesOutput) {
198		fmt.Fprintf(w, "Window: %s .. %s (%s)\n",
199			out.WindowStart.Format(time.RFC3339),
200			out.WindowEnd.Format(time.RFC3339),
201			windowDurationLabel(out.Since))
202		if out.AxisFilter != "" {
203			fmt.Fprintf(w, "Axis filter: %s\n", out.AxisFilter)
204		}
205		fmt.Fprintf(w, "Auto-acceptance rate: %.3f (%d / %d)\n",
206			out.AutoAcceptanceRate,
207			out.TotalRequests-out.TotalOverrides,
208			out.TotalRequests)
209		fmt.Fprintf(w, "Override disagreement rate: %.3f (%d overrides)\n",
210			out.OverrideDisagreementRate,
211			out.TotalOverrides)
212	
213		if len(out.OverrideClassBreakdown) == 0 {
214			fmt.Fprintln(w)
215			fmt.Fprintln(w, "No override events recorded in this window.")
216			return
217		}
218	
219		fmt.Fprintln(w)
220		tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
221		fmt.Fprintln(tw, "PROMPT_FEATURES\tAXIS\tMATCH\tCOUNT\tSUCCESS%\tSUCCESS\tSTALLED\tFAILED\tCANCELLED\tUNKNOWN")
222		for _, b := range sortOverrideBreakdownForDisplay(out.OverrideClassBreakdown) {
223			successPct := bucketSuccessRate(b) * 100
224			fmt.Fprintf(tw, "%s\t%s\t%t\t%d\t%.1f%%\t%d\t%d\t%d\t%d\t%d\n",
225				b.PromptFeatureBucket, b.Axis, b.Match, b.Count, successPct,
226				b.SuccessOutcomes, b.StalledOutcomes, b.FailedOutcomes,
227				b.CancelledOutcomes, b.UnknownOutcomes)
228		}
229		_ = tw.Flush()
230	}
231	
232	func windowDurationLabel(since string) string {
233		if since == "" {
234			return "default 7d"
235		}
236		return since
237	}
238	
239	// formatUsageWindowSince builds the date-range form
240	// "RFC3339..RFC3339" that internal/session.ParseUsageWindow accepts. We
241	// route through it (rather than a duration form) because the public
242	// UsageReport API only takes a string.
243	func formatUsageWindowSince(start, end time.Time) string {
244		return start.UTC().Format(time.RFC3339) + ".." + end.UTC().Format(time.RFC3339)
245	}
