1	package fizeau
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"strings"
8		"time"
9	
10		"github.com/DocumentDrivenDX/fizeau/internal/harnesses"
11		"github.com/DocumentDrivenDX/fizeau/internal/modelcatalog"
12		"github.com/DocumentDrivenDX/fizeau/internal/provider/utilization"
13		"github.com/DocumentDrivenDX/fizeau/internal/routing"
14	)
15	
16	var loadRoutingCatalog = modelcatalog.Default
17	
18	// ResolveRoute resolves an under-specified RouteRequest to a concrete
19	// (Harness, Provider, Model) decision per CONTRACT-003.
20	//
21	// The implementation delegates to internal/routing.Resolve — the single
22	// routing engine that consolidates DDx-side harness-tier ranking and
23	// fiz-side provider failover ordering.
24	func (s *service) ResolveRoute(ctx context.Context, req RouteRequest) (*RouteDecision, error) {
25		if err := ValidatePowerBounds(req.MinPower, req.MaxPower); err != nil {
26			return nil, err
27		}
28		if err := ValidateRole(req.Role); err != nil {
29			return nil, err
30		}
31		if err := ValidateCorrelationID(req.CorrelationID); err != nil {
32			return nil, err
33		}
34		if req.Harness != "" && req.Model != "" {
35			canonical := harnesses.ResolveHarnessAlias(req.Harness)
36			if !s.registry.Has(canonical) {
37				return nil, fmt.Errorf("unknown harness %q", req.Harness)
38			}
39			cfg, _ := s.registry.Get(canonical)
40			if err := validateExplicitHarnessModel(canonical, cfg, req.Model, req.Provider); err != nil {
41				return nil, err
42			}
43		}
44		s.ensurePrimaryQuotaRefresh(ctx, quotaRefreshAsync)
45		cat := serviceRoutingCatalog()
46		profile := req.Profile
47		powerPolicy := routePowerPolicyForRequest(cat, req)
48		modelRef := req.ModelRef
49		providerPreference, err := providerPreferenceForProfile(cat, profile)
50		if err != nil {
51			return &RouteDecision{
52				RequestedProfile: req.Profile,
53				PowerPolicy:      powerPolicy,
54			}, err
55		}
56		in := s.buildRoutingInputsWithCatalog(ctx, cat)
57	
58		resolvedModel, modelCandidates, modelErr := s.resolveModelConstraint(req.Harness, req.Provider, req.Model, in, cat)
59		if modelErr != nil {
60			result := &RouteDecision{
61				RequestedProfile: req.Profile,
62				PowerPolicy:      powerPolicy,
63				Candidates:       modelCandidates,
64			}
65			s.annotateRouteDecisionEvidence(result)
66			return result, publicRoutingError(modelErr, result.Candidates)
67		}
68	
69		rReq := routing.Request{
70			Profile:               profile,
71			ModelRef:              modelRef,
72			Model:                 resolvedModel,
73			Provider:              req.Provider,
74			Harness:               req.Harness,
75			Reasoning:             effectiveReasoningString(req.Reasoning),
76			Permissions:           req.Permissions,
77			ProviderPreference:    providerPreference,
78			EstimatedPromptTokens: req.EstimatedPromptTokens,
79			RequiresTools:         req.RequiresTools,
80			CorrelationID:         req.CorrelationID,
81		}
82		rReq.MinPower, rReq.MaxPower = routePowerBoundsForRequest(req, powerPolicy)
83		s.applyRouteAttemptCooldowns(&in)
84		dec, err := routing.Resolve(rReq, in)
85		if err != nil {
86			if escalated, edec, eerr := escalateProfileLadder(rReq, in, err); escalated {
87				dec = edec
88				err = eerr
89			}
90		}
91		result := routeDecisionFromInternal(dec)
92		if err != nil {
93			if result == nil {
94				result = &RouteDecision{}
95			}
96			result.RequestedProfile = req.Profile
97			result.PowerPolicy = powerPolicy
98			s.annotateRouteDecisionEvidence(result)
99			return result, publicRoutingError(err, result.Candidates)
100		}
101		s.applyStickyRouteLease(req.CorrelationID, result)
102		if result != nil && result.Endpoint == "" {
103			_, endpoint, _ := splitEndpointProviderRef(result.Provider)
104			result.Endpoint = endpoint
105		}
106		s.annotateRouteDecisionEvidence(result)
107		// Cache the decision so RouteStatus can surface LastDecision.
108		if result != nil {
109			result.RequestedProfile = req.Profile
110			result.PowerPolicy = powerPolicy
111			result.Model = resolveSubprocessModelAlias(result.Harness, result.Model)
112			result.Power = catalogPowerForModel(cat, result.Model)
113		}
114		s.cacheRouteDecision(req.Model, result)
115		return result, nil
116	}
