118	func routeDecisionFromInternal(dec *routing.Decision) *RouteDecision {
119		if dec == nil {
120			return nil
121		}
122		return &RouteDecision{
123			Harness:        dec.Harness,
124			Provider:       dec.Provider,
125			Endpoint:       dec.Endpoint,
126			ServerInstance: dec.ServerInstance,
127			Model:          dec.Model,
128			Reason:         dec.Reason,
129			Candidates:     routeCandidatesFromInternal(dec.Candidates),
130		}
131	}
132	
133	func routeCandidatesFromInternal(candidates []routing.Candidate) []RouteCandidate {
134		if len(candidates) == 0 {
135			return nil
136		}
137		out := make([]RouteCandidate, len(candidates))
138		for i, candidate := range candidates {
139			out[i] = routeCandidateFromInternal(candidate)
140		}
141		return out
142	}
143	
144	func routeCandidateFromInternal(candidate routing.Candidate) RouteCandidate {
145		return RouteCandidate{
146			Harness:            candidate.Harness,
147			Provider:           candidate.Provider,
148			Endpoint:           candidate.Endpoint,
149			ServerInstance:     candidate.ServerInstance,
150			Model:              candidate.Model,
151			Score:              candidate.Score,
152			CostUSDPer1kTokens: candidate.CostUSDPer1kTokens,
153			CostSource:         candidate.CostSource,
154			Eligible:           candidate.Eligible,
155			Reason:             candidate.Reason,
156			FilterReason:       publicFilterReason(candidate),
