11	// RouteStatus returns live routing state for configured providers/models.
12	// It is the operator dashboard view: cooldowns, recent decisions, and
13	// per-candidate health. Distinct from per-request ResolveRoute.
14	func (s *service) RouteStatus(ctx context.Context) (*RouteStatusReport, error) {
15		s.ensurePrimaryQuotaRefresh(ctx, quotaRefreshAsync)
16		sc := s.opts.ServiceConfig
17		report := &RouteStatusReport{
18			GeneratedAt: time.Now(),
19		}
20		// ADR-006 §5: populate routing-quality over a recent window
21		// (RouteStatusRoutingQualityWindow) regardless of whether a route
22		// catalog is configured — the metric reflects Execute traffic, not
23		// configured routes.
24		if s != nil && s.routingQuality != nil {
25			recent := s.routingQuality.snapshotRecent(RouteStatusRoutingQualityWindow, time.Time{})
26			report.RoutingQuality = computeRoutingQualityMetricsFromRecords(recent)
27		}
28		if sc == nil {
29			return report, nil
30		}
31	
32		cooldown := s.routeAttemptTTL()
33		activeAttempts := s.activeRouteAttempts(report.GeneratedAt, cooldown)
34	
35		entries := make(map[string]*RouteStatusEntry)
36		order := make([]string, 0)
37		for i, providerName := range sc.ProviderNames() {
38			provider, ok := sc.Provider(providerName)
39			if !ok {
40				continue
41			}
42			model := provider.Model
43			if model == "" {
44				model = providerName
45			}
46			entry, ok := entries[model]
47			if !ok {
48				entry = &RouteStatusEntry{Model: model, Strategy: "auto"}
49				if cached, ok := s.lookupRouteDecision(model); ok {
50					entry.LastDecision = cached.decision
51					entry.LastDecisionAt = cached.at
52					entry.SelectedEndpoint = cached.decision.Endpoint
53					entry.SelectedServerInstance = cached.decision.ServerInstance
54					entry.Sticky = cached.decision.Sticky
55				}
56				entries[model] = entry
57				order = append(order, model)
58			}
59			cs := RouteCandidateStatus{
60				Provider:       providerName,
61				Model:          model,
62				ServerInstance: serverinstance.Normalize(provider.BaseURL, provider.ServerInstance),
63				Priority:       len(sc.ProviderNames()) - i,
64			}
65			if attemptCooldown := routeAttemptCandidateCooldown(activeAttempts, providerName, model, cooldown); attemptCooldown != nil {
66				cs.Cooldown = attemptCooldown
67			}
68			cs.Healthy = cs.Cooldown == nil
69			entry.Candidates = append(entry.Candidates, cs)
70		}
71	
72		report.Routes = make([]RouteStatusEntry, 0, len(order))
73		for _, model := range order {
74			report.Routes = append(report.Routes, *entries[model])
75		}
76	
77		return report, nil
78	}
