80	func routeAttemptCandidateCooldown(records []routehealth.Record, providerName, model string, cooldown time.Duration) *CooldownState {
81		var newest *routehealth.Record
82		for i := range records {
83			record := &records[i]
84			if record.Key.Provider == "" {
85				continue
86			}
87			if providerName != "" && record.Key.Provider != providerName {
88				continue
89			}
90			if record.Key.Model != "" && model != "" && record.Key.Model != model {
91				continue
92			}
93			if newest == nil || record.RecordedAt.After(newest.RecordedAt) {
94				newest = record
95			}
96		}
97		if newest == nil {
98			return nil
99		}
100		return routeAttemptCooldown(*newest, cooldown)
101	}
